struct UnionFind {
    parent: Vec<usize>,
    size: Vec<usize>,
    n: usize,
}

impl UnionFind {
    /// n頂点0辺の無向グラフを作成
    /// ### 計算量 O(N)
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
            n,
        }
    }

    /// 頂点aの代表元を返す
    /// ### 計算量 ならし O(α(N))
    fn leader(&mut self, a: usize) -> usize {
        if self.parent[a] == a {
            a
        } else {
            self.parent[a] = self.leader(self.parent[a]);
            self.parent[a]
        }
    }

    /// 辺(a, b)を追加する
    /// 連結だった場合はその代表元、非連結だった場合は新たな代表元を返す
    /// ### 計算量 ならし O(α(N))
    fn merge(&mut self, a: usize, b: usize) -> usize {
        let pa = self.leader(a);
        let pb = self.leader(b);
        if pa == pb {
            return pa;
        }
        let (large, small) = if self.size[pa] >= self.size[pb] {
            (pa, pb)
        } else {
            (pb, pa)
        };
        self.parent[small] = large;
        self.size[large] += self.size[small];
        large
    }

    /// 頂点aとbが連結かどうかを返す
    /// ### 計算量 ならし O(α(N))
    fn same(&mut self, a: usize, b: usize) -> bool {
        self.leader(a) == self.leader(b)
    }

    /// 頂点aの属する連結成分のサイズを返す
    /// ### 計算量 ならし O(α(N))
    fn size(&mut self, a: usize) -> usize {
        let la = self.leader(a);
        self.size[la]
    }

    /// グラフを連結成分に分けて返す
    /// 戻り値は「一つの連結成分の頂点番号リスト」のリスト
    /// ### 計算量 O(N)
    fn groups(&mut self) -> Vec<Vec<usize>> {
        let mut leader_to_idx = vec![self.n; self.n];
        let mut idx = 0;
        let mut result: Vec<Vec<usize>> = vec![];

        for i in 0..self.n {
            let l = self.leader(i);
            if leader_to_idx[l] == self.n {
                leader_to_idx[l] = idx;
                idx += 1;
                result.push(vec![]);
            }
            result[leader_to_idx[l]].push(i);
        }
        result
    }
}

