fn columbination(n: u64, r: u64, md: u64) -> u64 {
    if r > n {
        return 0;
    }
    let mut num = 1u64;
    let mut den = 1u64;
    for i in 0..r {
        num = num * ((n - i) % md) % md;
        den = den * ((i + 1) % md) % md;
    }
    num * power(den, md - 2, md) % md
}

