fn generate_palindromes(max_digits: u32) -> Vec<u64> {
    let mut res = Vec::new();

    for i in 0..10 {
        res.push(i as u64);
    }

    for length in 2..=max_digits {
        let is_odd = length % 2 != 0;
        let half_len = (length + 1) / 2;

        let start = 10_u64.pow(half_len - 1);
        let end = 10_u64.pow(half_len);

        for i in start..end {
            let s = i.to_string();
            let rev_s: String = s.chars().rev().collect();

            let full_s = if is_odd {
                format!("{}{}", s, &rev_s[1..])
            } else {
                format!("{}{}", s, rev_s)
            };

            if let Ok(num) = full_s.parse::<u64>() {
                res.push(num);
            }
        }
    }

    res.sort();
    res
}

