fn get_tousa(a: &[i32]) -> usize {
    let n = a.len();
    if n <= 2 {
        return n;
    }

    let mut dp = vec![HashMap::new(); n];
    let mut max_len = 2;

    for i in 0..n {
        for j in 0..i {
            let diff = a[i] - a[j];
            let len = *dp[j].get(&diff).unwrap_or(&1) + 1;
            dp[i].insert(diff, len);
            max_len = max_len.max(len);
        }
    }
    max_len
}

