fn power(mut a: u128, mut b: u128, m: u128) -> u128 {
    let mut res = 1;
    a %= m;
    while b > 0 {
        if b % 2 == 1 {
            res = (res * a) % m;
        }
        a = (a * a) % m;
        b /= 2;
    }
    res
