use itertools::Itertools;
use proconio::input;
use proconio::marker::Usize1;

struct Graph {
    n: usize,
    edges: Vec<Vec<(usize, i64)>>,
    h: u64,
    directed: bool,
}

impl Graph {
    /// グラフを新規作成
    /// ## 入力
    /// * `n` - 頂点数
    /// * `directed` - 有向/無向グラフ(有向グラフなら`true`)
    /// ### 計算量 O(N)
    fn new(n: usize, directed: bool) -> Self {
        Self {
            n,
            edges: vec![vec![]; n],
            h: 0,
            directed,
        }
    }

    /// 頂点aからbに辺を張る
    /// ## 入力
    /// * `a` `b` - 頂点
    /// * `x` - コスト
    /// ### 計算量 O(1)
    fn add(&mut self, a: usize, b: usize, x: i64) {
        self.edges[a].push((b, x));
        if !self.directed {
            self.edges[b].push((a, x));
        }
        self.h += 1;
    }

    /// グラフの辺の総数
    /// ### 計算量 O(1)
    fn edge_cnt(&self) -> u64 {
        self.h
    }

    /// 頂点aの次数（隣接辺の数）
    /// ### 計算量 O(1)
    fn degree(&self, a: usize) -> usize {
        self.edges[a].len()
    }

    /// 頂点aの隣接頂点リスト
    /// ## 出力
    /// 隣接頂点がある場合`Some(&Vec)` ない場合`None`
    /// ### 計算量 O(1)
    fn get(&self, a: usize) -> Option<&Vec<(usize, i64)>> {
        if !self.edges[a].is_empty() {
            Some(&self.edges[a])
        } else {
            None
        }
    }

    /// 頂点sからのオイラーツアー
    /// ## 出力
    /// 頂点sからのオイラーツアー（頂点の訪問順列）
    /// ### 計算量 O(N+M)
    fn euler_tour(&self, s: usize) -> Vec<usize> {
        let mut tour = Vec::new();
        let mut visited = vec![false; self.n];

        let mut stack = vec![(s, true)];

        while let Some((v, is_pre)) = stack.pop() {
            if is_pre {
                if visited[v] {
                    continue;
                }
                visited[v] = true;

                tour.push(v);

                stack.push((v, false));

                for &(next_v, _) in self.edges[v].iter().rev() {
                    if !visited[next_v] {
                        stack.push((next_v, true));
                    }
                }
            } else {
                tour.push(v);
            }
        }
        tour
    }

    /// BFSによる頂点sから各頂点への最短ステップ数
    /// ## 出力
    /// `vec[i]` - 頂点sから頂点iへの最短ステップ数（到達不可能なら`-1`）
    /// ### 計算量 O(N+M)
    fn bfs(&self, s: usize) -> Vec<i64> {
        let mut dist = vec![-1i64; self.n];
        let mut que = std::collections::VecDeque::new();
        dist[s] = 0;
        que.push_back(s);
        while let Some(v) = que.pop_front() {
            for &(next_v, _) in &self.edges[v] {
                if dist[next_v] == -1 {
                    dist[next_v] = dist[v] + 1;
                    que.push_back(next_v);
                }
            }
        }
        dist
    }

    /// ダイクストラ法による頂点sから各頂点への最小コスト（非負コストのみ）
    /// ## 出力
    /// `vec[i]` - 頂点sから頂点iへの最小コスト（到達不可能なら`i64::MAX`）
    /// ### 計算量 O((N+M) log N)
    fn djk(&self, s: usize) -> Vec<i64> {
        let mut dist = vec![i64::MAX; self.n];
        let mut pq = std::collections::BinaryHeap::new();
        dist[s] = 0;
        pq.push(std::cmp::Reverse((0i64, s)));
        while let Some(std::cmp::Reverse((d, v))) = pq.pop() {
            if d > dist[v] {
                continue;
            }
            for &(next_v, cost) in &self.edges[v] {
                if dist[v] + cost < dist[next_v] {
                    dist[next_v] = dist[v] + cost;
                    pq.push(std::cmp::Reverse((dist[next_v], next_v)));
                }
            }
        }
        dist
    }

    /// サイクル検出（有向・無向を自動判定）
    /// ## 出力
    /// サイクルがあるなら`true`
    /// ### 計算量 O(N+M)
    fn cycle(&self) -> bool {
        if self.directed {
            self.cycle_directed()
        } else {
            self.cycle_undirected()
        }
    }

    fn cycle_undirected(&self) -> bool {
        fn has_cycle(
            v: usize,
            parent: usize,
            g: &Vec<Vec<(usize, i64)>>,
            seen: &mut Vec<bool>,
        ) -> bool {
            seen[v] = true;
            for &(next_v, _) in &g[v] {
                if next_v == parent {
                    continue;
                }
                if seen[next_v] || has_cycle(next_v, v, g, seen) {
                    return true;
                }
            }
            false
        }
        let mut seen = vec![false; self.n];
        for s in 0..self.n {
            if !seen[s] && has_cycle(s, s, &self.edges, &mut seen) {
                return true;
            }
        }
        false
    }

    fn cycle_directed(&self) -> bool {
        fn has_cycle(
            v: usize,
            g: &Vec<Vec<(usize, i64)>>,
            seen: &mut Vec<bool>,
            in_stack: &mut Vec<bool>,
        ) -> bool {
            seen[v] = true;
            in_stack[v] = true;
            for &(next_v, _) in &g[v] {
                if !seen[next_v] && has_cycle(next_v, g, seen, in_stack) {
                    return true;
                } else if in_stack[next_v] {
                    return true;
                }
            }
            in_stack[v] = false;
            false
        }
        let mut seen = vec![false; self.n];
        let mut in_stack = vec![false; self.n];
        for s in 0..self.n {
            if !seen[s] && has_cycle(s, &self.edges, &mut seen, &mut in_stack) {
                return true;
            }
        }
        false
    }

    /// ワーシャルフロイド法による全頂点間最短コスト
    /// ## 出力
    /// `vec[i][j]` - 頂点iから頂点jへの最短コスト（到達不可能なら`i64::MAX/2`）
    /// ### 計算量 O(N^3)
    fn warshall(&self) -> Vec<Vec<i64>> {
        let inf = i64::MAX / 2;
        let mut dist = vec![vec![inf; self.n]; self.n];
        for i in 0..self.n {
            dist[i][i] = 0;
        }
        for u in 0..self.n {
            for &(v, w) in &self.edges[u] {
                dist[u][v] = dist[u][v].min(w);
            }
        }
        for k in 0..self.n {
            for i in 0..self.n {
                for j in 0..self.n {
                    if dist[i][k] < inf && dist[k][j] < inf {
                        dist[i][j] = dist[i][j].min(dist[i][k] + dist[k][j]);
                    }
                }
            }
        }
        dist
    }

    /// ベルマンフォード法による頂点sから各頂点への最小コスト（負のコストも可）
    /// ## 出力
    /// * `vec[i]` - 頂点sから頂点iへの最小コスト（到達不可能なら`i64::MAX`）
    /// * `bool` - 負閉路が存在するなら`true`
    /// ### 計算量 O(NM)
    fn bellman(&self, s: usize) -> (Vec<i64>, bool) {
        let mut dist = vec![i64::MAX; self.n];
        dist[s] = 0;
        for _ in 0..self.n - 1 {
            for v in 0..self.n {
                if dist[v] == i64::MAX {
                    continue;
                }
                for &(next_v, cost) in &self.edges[v] {
                    if dist[v] + cost < dist[next_v] {
                        dist[next_v] = dist[v] + cost;
                    }
                }
            }
        }
        let mut has_negative_cycle = false;
        for v in 0..self.n {
            if dist[v] == i64::MAX {
                continue;
            }
            for &(next_v, cost) in &self.edges[v] {
                if dist[v] + cost < dist[next_v] {
                    has_negative_cycle = true;
                }
            }
        }
        (dist, has_negative_cycle)
    }

    /// クラスカル法による最小全域木
    /// ## 出力
    /// * `Some((合計コスト, 辺のリスト(頂点, 頂点, コスト)))` - 存在する場合
    /// * `None` - 非連結で存在しない場合
    /// ### 計算量 O(M log M)
    fn kruskal(&self) -> Option<(i64, Vec<(usize, usize, i64)>)> {
        let mut edges: Vec<(i64, usize, usize)> = vec![];
        for u in 0..self.n {
            for &(v, w) in &self.edges[u] {
                if u < v {
                    edges.push((w, u, v));
                }
            }
        }
        edges.sort();
        use ac_library::Dsu;
        let mut uf = Dsu::new(self.n);
        let mut total_cost = 0i64;
        let mut mst_edges = vec![];
        for (w, u, v) in edges {
            if !uf.same(u, v) {
                uf.merge(u, v);
                total_cost += w;
                mst_edges.push((u, v, w));
            }
            if mst_edges.len() == self.n - 1 {
                break;
            }
        }
        if mst_edges.len() < self.n - 1 {
            None
        } else {
            Some((total_cost, mst_edges))
        }
    }

    /// 二部グラフ判定（無向グラフ用）
    /// ## 出力
    /// 二部グラフなら`true`
    /// ### 計算量 O(N+M)
    fn is_bipartite(&self) -> bool {
        debug_assert!(!self.directed, "is_bipartiteは無向グラフ専用です");
        let mut color = vec![-1i64; self.n];
        for start in 0..self.n {
            if color[start] != -1 {
                continue;
            }
            let mut que = std::collections::VecDeque::new();
            color[start] = 0;
            que.push_back(start);
            while let Some(v) = que.pop_front() {
                for &(next_v, _) in &self.edges[v] {
                    if color[next_v] == -1 {
                        color[next_v] = 1 - color[v];
                        que.push_back(next_v);
                    } else if color[next_v] == color[v] {
                        return false;
                    }
                }
            }
        }
        true
    }

    /// 連結成分分解（無向グラフ用）
    /// ## 出力
    /// `vec[i]` - 連結成分iに含まれる頂点リスト
    /// ### 計算量 O(N+M)
    fn conn_comp(&self) -> Vec<Vec<usize>> {
        debug_assert!(!self.directed, "conn_compは無向グラフ専用です");
        let mut seen = vec![false; self.n];
        let mut components = vec![];
        for start in 0..self.n {
            if seen[start] {
                continue;
            }
            let mut component = vec![];
            let mut stack = vec![start];
            seen[start] = true;
            while let Some(v) = stack.pop() {
                component.push(v);
                for &(next_v, _) in &self.edges[v] {
                    if !seen[next_v] {
                        seen[next_v] = true;
                        stack.push(next_v);
                    }
                }
            }
            components.push(component);
        }
        components
    }

    /// トポロジカルソート（有向グラフ用）
    /// ## 出力
    /// * `Some(Vec<usize>)` - サイクルがない場合のソート結果
    /// * `None` - サイクルが存在する場合
    /// ### 計算量 O(N+M)
    fn topo(&self) -> Option<Vec<usize>> {
        debug_assert!(self.directed, "topoは有向グラフ専用です");
        let mut in_degree = vec![0usize; self.n];
        for u in 0..self.n {
            for &(v, _) in &self.edges[u] {
                in_degree[v] += 1;
            }
        }
        let mut que = std::collections::VecDeque::new();
        for i in 0..self.n {
            if in_degree[i] == 0 {
                que.push_back(i);
            }
        }
        let mut result = vec![];
        while let Some(v) = que.pop_front() {
            result.push(v);
            for &(next_v, _) in &self.edges[v] {
                in_degree[next_v] -= 1;
                if in_degree[next_v] == 0 {
                    que.push_back(next_v);
                }
            }
        }
        if result.len() == self.n {
            Some(result)
        } else {
            None
        }
    }

    /// 木の直径（最も遠い2頂点間のステップ数）
    /// ### 計算量 O(N+M)
    fn tree_diameter(&self) -> i64 {
        let farthest = |s: usize| -> usize {
            self.bfs(s)
                .iter()
                .enumerate()
                .max_by_key(|&(_, d)| d)
                .unwrap()
                .0
        };
        let u = farthest(0);
        let v = farthest(u);
        self.bfs(u)[v]
    }
}

