        if *back < value {
            self.deque.pop_back();
        } else {
            break;
        }
    }
    self.deque.push_back((index, value));
}

fn pop(&mut self, index: usize) {
    if let Some(&(front_index, _)) = self.deque.front() {
        if front_index == index {
            self.deque.pop_front();
        }
    }
}

